package com.loja.assinatura;

import java.time.Duration;
import java.util.UUID;
import org.springframework.jdbc.core.simple.JdbcClient;
import org.springframework.stereotype.Service;

@Service
public class RenovarAssinaturaService {
    private final JdbcClient db;

    public RenovarAssinaturaService(JdbcClient db) { this.db = db; }

    public void renovar(UUID id) {
        Assinatura a = db.sql("select * from assinatura where id = ?").param(id).query(Assinatura.class).optional()
                .orElseThrow(() -> new RuntimeException("not found"));
        a.setFimPeriodo(a.getFimPeriodo().plus(Duration.ofDays(30)));
        db.sql("update assinatura set fim_periodo = ? where id = ?").params(a.getFimPeriodo(), id).update();
    }
}

