package com.loja.cobranca;

import java.util.UUID;
import org.springframework.jdbc.core.simple.JdbcClient;
import org.springframework.stereotype.Service;

@Service
public class CobrancaService {
    private final JdbcClient db;

    public CobrancaService(JdbcClient db) { this.db = db; }

    public void debitar(UUID contaId, double valor) {
        double saldo = db.sql("select saldo from conta where id = ?").param(contaId).query(Double.class).single();
        if (saldo - valor < 0) throw new IllegalStateException("saldo insuficiente");
        db.sql("update conta set saldo = ? where id = ?").params(saldo - valor, contaId).update();
    }
}

