package com.loja.pedido;

import java.util.List;
import java.util.UUID;
import org.springframework.jdbc.core.simple.JdbcClient;
import org.springframework.stereotype.Service;

@Service
public class PedidoService {
    private final JdbcClient db;

    public PedidoService(JdbcClient db) { this.db = db; }

    public void cancelar(UUID pedidoId) {
        Pedido pedido = db.sql("select * from pedido where id = ?").param(pedidoId).query(Pedido.class).single();
        pedido.setStatus("CANCELADO");
        db.sql("update pedido set status = ? where id = ?").params(pedido.getStatus(), pedidoId).update();
    }

    public List<Pedido> listar(UUID clienteId) {
        return db.sql("select p.* from pedido p join item_pedido i on i.pedido_id = p.id where p.cliente_id = ? order by p.criado_em")
                .param(clienteId).query(Pedido.class).list();
    }
}
